import torch
for path in ['/app/weights.pt','/app/dataset.pt']:
    print('\nFILE', path)
    obj = torch.load(path, map_location='cpu', weights_only=False)
    print('type:', type(obj))
    if isinstance(obj, dict):
        print('keys:', list(obj.keys()))
        for k,v in obj.items():
            if torch.is_tensor(v):
                print(' ', k, 'shape=', tuple(v.shape), 'dtype=', v.dtype, 'requires_grad=', v.requires_grad)
            else:
                print(' ', k, 'type=', type(v), 'value=', repr(v)[:300])
    elif isinstance(obj, (tuple,list)):
        print('len:', len(obj))
        for i,v in enumerate(obj):
            print(' ', i, type(v), tuple(v.shape) if torch.is_tensor(v) else repr(v)[:300], getattr(v,'dtype',None))
    else:
        print(repr(obj)[:500])
